package nir.com.neonvegasslots;
import static org.junit.Assert.*;import android.graphics.*;import android.view.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @GraphicsMode(GraphicsMode.Mode.NATIVE) public class CanvasAuxFeedbackTest{
 @Test public void auxiliaryControlsRouteOnceWithoutSpending()throws Exception{
  SlotsView v=new SlotsView(RuntimeEnvironment.getApplication());v.layout(0,0,720,1480);final int[] calls={0,0,0};v.setListener(new SlotsView.Listener(){public void onOutOfCoins(){}public void onSpinComplete(int s,long a,long b){}public void onBigWin(long a,long b){}public void onLevelUp(int l,long r){}public void saveState(){}public void onOpenPaytable(){calls[0]++;}public void onOpenShop(){calls[1]++;}public void onOpenMap(){calls[2]++;}});
  Bitmap b=Bitmap.createBitmap(720,1480,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));java.lang.reflect.Field f=SlotsView.class.getDeclaredField("chipPlus");f.setAccessible(true);RectF plus=(RectF)f.get(v);java.lang.reflect.Method top=SlotsView.class.getDeclaredMethod("trailTop");top.setAccessible(true);float[][] points={{648,129.6f},{plus.centerX(),plus.centerY()},{360,((Float)top.invoke(v))+30}};
  java.lang.reflect.Method scale=SlotsView.class.getDeclaredMethod("controlScale",int.class,long.class);scale.setAccessible(true);String saved=v.serialize();for(int i=0;i<3;i++){v.onTouchEvent(MotionEvent.obtain(0,0,0,points[i][0],points[i][1],0));assertEquals(.95f,(Float)scale.invoke(v,i+4,System.currentTimeMillis()),.001f);assertEquals(1,calls[i]);String[] before=saved.split(";",-1),after=v.serialize().split(";",-1);for(int n=0;n<before.length;n++)if(n!=3)assertEquals("field"+n,before[n],after[n]);v.draw(new Canvas(b));try(java.io.FileOutputStream o=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-aux-"+(i+4)+".png")){b.compress(Bitmap.CompressFormat.PNG,100,o);}v.onTouchEvent(MotionEvent.obtain(0,20,1,points[i][0],points[i][1],0));assertEquals(1,calls[i]);}
 }
}
